24	export async function getAllUsersWithStatus(): Promise<{ data: UserWithDetails[], error: any }> {
25	    const supabase = await createSupabaseAdminClient();
26	
27	    try {
28	        // member.membersからユーザー情報を取得
29	        const { data: members, error: membersError } = await supabase
30	            .schema('member')
31	            .from('members')
32	            .select(`
