1	-- Security fix: Enforce least-privilege on all schemas
2	--
3	-- Problem found in production:
4	--   1. member schema: RLS was disabled, allowing anon to read/write all member data
5	--   2. Both schemas: ALTER DEFAULT PRIVILEGES granted ALL to anon (overly broad)
6	--   3. attendance tables: anon had INSERT/UPDATE/DELETE in addition to SELECT
7	--
8	-- This migration:
9	--   - Re-enables RLS on all tables (FORCE for extra safety)
10	--   - Revokes excess anon grants; anon only gets what kiosk strictly needs:
11	--       * EXECUTE on attendance.record_attendance_by_card (direct RPC from kiosk)
12	--       * SELECT on attendance.temp_registrations (Realtime QR channel subscription)
13	--   - Adds missing authenticated READ policies on team_leaders / generation_roles
14	
15	
16	-- ================================================================
17	-- MEMBER SCHEMA: Enable RLS and revoke anon direct table access
18	-- ================================================================
19	
20	-- Re-enable RLS (idempotent)
21	ALTER TABLE member.members ENABLE ROW LEVEL SECURITY;
22	ALTER TABLE member.teams ENABLE ROW LEVEL SECURITY;
23	ALTER TABLE member.member_team_relations ENABLE ROW LEVEL SECURITY;
24	ALTER TABLE member.team_leaders ENABLE ROW LEVEL SECURITY;
25	ALTER TABLE member.generation_roles ENABLE ROW LEVEL SECURITY;
26	
27	-- Force RLS even for table owner (prevents accidental bypass via service key outside policies)
28	ALTER TABLE member.members FORCE ROW LEVEL SECURITY;
29	ALTER TABLE member.teams FORCE ROW LEVEL SECURITY;
30	ALTER TABLE member.member_team_relations FORCE ROW LEVEL SECURITY;
31	ALTER TABLE member.team_leaders FORCE ROW LEVEL SECURITY;
32	ALTER TABLE member.generation_roles FORCE ROW LEVEL SECURITY;
33	
34	-- Revoke all direct anon access on member tables
35	-- (anon has no business reading member data directly)
36	REVOKE ALL ON member.members FROM anon;
37	REVOKE ALL ON member.teams FROM anon;
38	REVOKE ALL ON member.member_team_relations FROM anon;
39	REVOKE ALL ON member.team_leaders FROM anon;
40	REVOKE ALL ON member.generation_roles FROM anon;
41	
42	-- Fix default privileges so future tables don't auto-grant anon
43	ALTER DEFAULT PRIVILEGES IN SCHEMA member REVOKE ALL ON TABLES FROM anon;
44	
45	-- Add missing READ policies for authenticated users on team_leaders / generation_roles
46	DO $$
47	BEGIN
48	  IF NOT EXISTS (
49	    SELECT 1 FROM pg_policies
50	    WHERE schemaname = 'member' AND tablename = 'team_leaders'
51	      AND policyname = 'Allow read access to authenticated users on team_leaders'
52	  ) THEN
53	    CREATE POLICY "Allow read access to authenticated users on team_leaders"
54	      ON member.team_leaders FOR SELECT TO authenticated USING (true);
55	  END IF;
56	
57	  IF NOT EXISTS (
58	    SELECT 1 FROM pg_policies
59	    WHERE schemaname = 'member' AND tablename = 'generation_roles'
60	      AND policyname = 'Allow read access to authenticated users on generation_roles'
